import RNA, random, time, multiprocessing as mp
target = ".....((.((.((...)).((....))...)))).((.((.((...)).((....))...))))....."
n=len(target)
def fold(s): return RNA.fold_compound(s).mfe()[0]
def dist(s): return RNA.bp_distance(fold(s), target)

def worker(seed):
    random.seed(seed)
    for _ in range(500):
        start=''.join(random.choice('ACGU') for _ in range(n))
        seq,d = RNA.inverse_fold(start, target)
        if d==0 and fold(seq)==target:
            return seq
    return None

if __name__=='__main__':
    with mp.Pool(64) as p:
        for r in p.imap_unordered(worker, range(256)):
            if r: print("SOLVED", r); p.terminate(); break
